const raw = $input.first().json;
const results = Array.isArray(raw) ? raw : [raw];
const today = new Date().toISOString().split('T')[0];

return results.map(r => ({
  json: {
    'Date': today,
    'Keyword': r.keyword || '',
    'Google Position': r.googlePosition || r.currentPosition || '',
    'Position Change': r.positionChange || 0,
    'Has Featured Snippet': r.hasFeaturedSnippet ? 'Yes' : 'No',
    'Has AI Overview': r.hasAiOverview ? 'Yes' : 'No',
    'ChatGPT Mentioned': r.chatgptMentioned ? 'Yes' : 'No',
    'ChatGPT Context': (r.chatgptContext || '').slice(0, 200),
    'Perplexity Mentioned': r.perplexityMentioned ? 'Yes' : 'No',
    'Perplexity Context': (r.perplexityContext || '').slice(0, 200),
    'Claude Mentioned': r.claudeMentioned ? 'Yes' : 'No',
    'AI Visibility Score': [
      r.chatgptMentioned, r.perplexityMentioned, r.claudeMentioned, r.geminiMentioned
    ].filter(Boolean).length + '/4'
  }
}));
